create function pn_private.valid_library_document(d jsonb, ready boolean) returns boolean language plpgsql stable set search_path='' as $$
declare i jsonb; seen uuid[]='{}';
begin
 if not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='library-draft-v1'),d) then return false;end if;
 if ready and (length(btrim(d->>'title'))=0 or jsonb_array_length(d->'items')=0) then return false;end if;
 for i in select value from jsonb_array_elements(d->'items') loop
  if (i->>'id')::uuid=any(seen) then return false;end if;seen=array_append(seen,(i->>'id')::uuid);
  if (d->>'kind'='cards')<>(i->>'kind'='card') then return false;end if;
  if ready and length(btrim(i->>'prompt'))=0 then return false;end if;
  if i->>'kind'='interactive' and not pn_private.valid_public_tool(i->'tool') then return false;end if;
  if ready and i->>'kind'='card' and (exists(select 1 from jsonb_array_elements_text(i->'options') o where length(btrim(o))=0) or (select count(distinct lower(btrim(o))) from jsonb_array_elements_text(i->'options') o)<>4) then return false;end if;
 end loop;return true;
exception when others then return false;
end $$;
create table pn_private.sample_accounts(owner_id uuid primary key references auth.users(id), namespace text not null unique default 'recording-v1', controller uuid, lease_until timestamptz);
alter table pn_private.sample_accounts enable row level security;
revoke all on pn_private.sample_accounts from public,anon,authenticated;
create function public.is_sample_teacher() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from pn_private.sample_accounts where owner_id=auth.uid())$$;
revoke all on function public.is_sample_teacher() from public,anon;grant execute on function public.is_sample_teacher() to authenticated;
create policy sample_classes_only on public.classes as restrictive for all to authenticated using(not public.is_sample_teacher() or runtime_mode='demo') with check(not public.is_sample_teacher() or runtime_mode='demo');
create function public.sample_control(p_token uuid,p_takeover boolean default false,p_acquire boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare a pn_private.sample_accounts;
begin
 if auth.uid() is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 select * into a from pn_private.sample_accounts where owner_id=auth.uid() for update;
 if not found then return '{"ok":true}';end if;
 if p_token is null then return '{"error":"CONFLICT"}';end if;
 if p_acquire then
  if a.controller is not null and a.controller<>p_token and a.lease_until>now() and not p_takeover then return '{"error":"CONFLICT"}';end if;
  if a.controller is distinct from p_token then
   update pn_private.presentations set revoked=true,channel_epoch=gen_random_uuid() where owner_id=auth.uid() and not revoked;
  end if;
  update pn_private.sample_accounts set controller=p_token,lease_until=now()+interval '90 seconds' where owner_id=auth.uid();return '{"ok":true}';
 end if;
 if a.controller=p_token and a.lease_until>now() then return '{"ok":true}';end if;
 return '{"error":"CONFLICT"}';
end $$;
revoke all on function public.sample_control(uuid,boolean,boolean) from public,anon;grant execute on function public.sample_control(uuid,boolean,boolean) to authenticated;

create table public.question_sets(id uuid primary key,owner_id uuid references auth.users(id),source text not null check(source in ('system','teacher')),revision integer not null default 1,status text not null check(status in ('draft','ready','archived')),document jsonb not null check(pn_private.valid_library_document(document,false)),current_version integer not null default 0,check((source='system')=(owner_id is null)));
create table public.question_versions(set_id uuid not null references public.question_sets(id),version integer not null,document jsonb not null check(pn_private.valid_library_document(document,true)),created_at timestamptz not null default now(),primary key(set_id,version));
create table public.library_runs(id uuid primary key,owner_id uuid not null references auth.users(id),class_id uuid not null,class_label text not null,set_id uuid not null,version integer not null,lesson_date date not null,mode text not null check(mode in ('teach','assessment')),status text not null default 'active' check(status in ('active','closed')),position integer not null default 0 check(position between 0 and 4),revision integer not null default 1,form_id uuid not null default gen_random_uuid() unique,roster jsonb not null,synthetic boolean not null,foreign key(class_id,owner_id) references public.classes(id,owner_id),foreign key(set_id,version) references public.question_versions(set_id,version));
create table public.library_responses(run_id uuid not null references public.library_runs(id),student_id uuid not null,answers jsonb not null,revision integer not null default 1,correct integer not null check(correct between 0 and 5),status text not null check(status in ('received','review')),updated_at timestamptz not null default now(),primary key(run_id,student_id));
alter table public.question_sets enable row level security;alter table public.question_versions enable row level security;alter table public.library_runs enable row level security;alter table public.library_responses enable row level security;
revoke all on public.question_sets,public.question_versions,public.library_runs,public.library_responses from public,anon,authenticated;
grant select on public.question_sets,public.question_versions,public.library_runs,public.library_responses to authenticated;
create policy library_sets_read on public.question_sets for select to authenticated using(auth.jwt()->>'is_anonymous'='false' and (owner_id=auth.uid() or source='system'));
create policy library_versions_read on public.question_versions for select to authenticated using(exists(select 1 from public.question_sets s where s.id=set_id));
create policy library_runs_read on public.library_runs for select to authenticated using(owner_id=auth.uid() and auth.jwt()->>'is_anonymous'='false');
create policy library_responses_read on public.library_responses for select to authenticated using(exists(select 1 from public.library_runs r where r.id=run_id));
create function pn_private.library_set_dto(s public.question_sets) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('id',s.id,'source',s.source,'revision',s.revision,'status',s.status,'document',s.document,'version',s.current_version)$$;
create function pn_private.library_run_dto(r public.library_runs) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('id',r.id,'classId',r.class_id,'classLabel',r.class_label,'collectionId',r.set_id,'version',r.version,'document',v.document,'date',to_char(r.lesson_date,'YYYY-MM-DD'),'mode',r.mode,'status',r.status,'position',r.position,'revision',r.revision,'formId',r.form_id,'roster',r.roster,'synthetic',r.synthetic) from public.question_versions v where v.set_id=r.set_id and v.version=r.version$$;
create function pn_private.library_detail(r public.library_runs) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('run',pn_private.library_run_dto(r),'responses',coalesce((select jsonb_agg(jsonb_build_object('studentId',student_id,'answers',answers,'revision',revision,'correct',correct,'status',status) order by student_id) from public.library_responses where run_id=r.id),'[]'::jsonb))$$;

create function public.library_action(p_input jsonb,p_controller uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid=auth.uid();a text=p_input->>'action';s public.question_sets;r public.library_runs;v public.question_versions;c public.classes;old public.library_responses;roster jsonb;score integer;item jsonb;control jsonb;
begin
 if u is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 if not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='library-action-v1'),p_input) then return '{"error":"INVALID_INPUT"}';end if;
 if a not in ('list','detail') then control=public.sample_control(p_controller,false,false);if control ? 'error' then return control;end if;end if;
 if a='list' then return jsonb_build_object('sample',public.is_sample_teacher(),'collections',coalesce((select jsonb_agg(pn_private.library_set_dto(q) order by q.source,q.id) from public.question_sets q where q.owner_id=u or q.source='system'),'[]'::jsonb),'runs',coalesce((select jsonb_agg(pn_private.library_run_dto(q) order by q.lesson_date desc,q.id) from public.library_runs q where q.owner_id=u),'[]'::jsonb));
 elsif a='save' then
  if not pn_private.valid_library_document(p_input->'document',(p_input->>'ready')::boolean) then return '{"error":"INVALID_INPUT"}';end if;
  select * into s from public.question_sets where id=(p_input->>'id')::uuid for update;
  if found then
   if s.owner_id is distinct from u then return '{"error":"FORBIDDEN"}';end if;
   if s.revision<>(p_input->>'revision')::integer then return '{"error":"CONFLICT"}';end if;
   update public.question_sets set document=p_input->'document',status=case when (p_input->>'ready')::boolean then 'ready' else 'draft' end,revision=revision+1,current_version=current_version+case when (p_input->>'ready')::boolean then 1 else 0 end where id=s.id returning * into s;
  else
   if (p_input->>'revision')::integer<>0 then return '{"error":"CONFLICT"}';end if;
   insert into public.question_sets(id,owner_id,source,status,document,current_version) values((p_input->>'id')::uuid,u,'teacher',case when (p_input->>'ready')::boolean then 'ready' else 'draft' end,p_input->'document',case when (p_input->>'ready')::boolean then 1 else 0 end) returning * into s;
  end if;
  if (p_input->>'ready')::boolean then insert into public.question_versions(set_id,version,document) values(s.id,s.current_version,s.document);end if;
  return pn_private.library_set_dto(s);
 elsif a='archive' then
  update public.question_sets set status='archived',revision=revision+1 where id=(p_input->>'id')::uuid and owner_id=u and revision=(p_input->>'revision')::integer returning * into s;
  if not found then return '{"error":"CONFLICT"}';end if;return pn_private.library_set_dto(s);
 elsif a='roster' then
  select * into c from public.classes where id=(p_input->>'classId')::uuid and owner_id=u for update;if not found then return '{"error":"FORBIDDEN"}';end if;
  if exists(select 1 from public.students where id=(p_input->>'studentId')::uuid and (class_id<>c.id or owner_id<>u)) then return '{"error":"FORBIDDEN"}';end if;
  insert into public.students(id,owner_id,class_id,attendance_number,active) values((p_input->>'studentId')::uuid,u,c.id,(p_input->>'attendanceNumber')::integer,(p_input->>'active')::boolean) on conflict(id) do update set attendance_number=excluded.attendance_number,active=excluded.active,revision=students.revision+1;
  update public.classes set student_count=(select count(*) from public.students where class_id=c.id),revision=revision+1 where id=c.id;return '{"ok":true}';
 elsif a='start' then
  select * into c from public.classes where id=(p_input->>'classId')::uuid and owner_id=u for update;if not found then return '{"error":"FORBIDDEN"}';end if;
  select * into s from public.question_sets where id=(p_input->>'collectionId')::uuid and status='ready' and (owner_id=u or source='system');if not found then return '{"error":"FORBIDDEN"}';end if;
  select * into v from public.question_versions where set_id=s.id and version=(p_input->>'version')::integer;if not found or (p_input->>'mode'='assessment' and v.document->>'kind'<>'cards') then return '{"error":"INVALID_INPUT"}';end if;
  select * into r from public.library_runs where id=(p_input->>'id')::uuid;
  if found then if r.owner_id=u and r.class_id=c.id and r.set_id=s.id and r.version=v.version and r.mode=p_input->>'mode' and to_char(r.lesson_date,'YYYY-MM-DD')=p_input->>'date' then return pn_private.library_run_dto(r);else return '{"error":"CONFLICT"}';end if;end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'attendanceNumber',attendance_number) order by attendance_number),'[]'::jsonb) into roster from public.students where class_id=c.id and active;
  if jsonb_array_length(roster)=0 then return '{"error":"INVALID_INPUT"}';end if;
  insert into public.library_runs(id,owner_id,class_id,class_label,set_id,version,lesson_date,mode,roster,synthetic) values((p_input->>'id')::uuid,u,c.id,c.label,s.id,v.version,(p_input->>'date')::date,p_input->>'mode',roster,c.runtime_mode='demo') returning * into r;return pn_private.library_run_dto(r);
 end if;
 select * into r from public.library_runs where id=(p_input->>'id')::uuid and owner_id=u for update;if not found then return '{"error":"NOT_FOUND"}';end if;
 select * into v from public.question_versions where set_id=r.set_id and version=r.version;
 if a='detail' then return pn_private.library_detail(r);
 elsif a='position' or a='close' then
  if r.revision<>(p_input->>'revision')::integer or r.status<>'active' then return '{"error":"CONFLICT"}';end if;
  if a='position' then
   if (p_input->>'position')::integer>=jsonb_array_length(v.document->'items') then return '{"error":"INVALID_INPUT"}';end if;
   update public.library_runs set position=(p_input->>'position')::integer,revision=revision+1 where id=r.id returning * into r;
  else
   update public.library_runs set status='closed',revision=revision+1 where id=r.id returning * into r;
   update pn_private.presentations set revoked=true,channel_epoch=gen_random_uuid() where session_id=r.id;
  end if;return pn_private.library_run_dto(r);
 elsif a='response' then
  if r.mode<>'assessment' or r.form_id<>(p_input->>'formId')::uuid or r.version<>(p_input->>'version')::integer or not exists(select 1 from jsonb_array_elements(r.roster) st where st->>'id'=p_input->>'studentId') or jsonb_array_length(p_input->'answers')<>jsonb_array_length(v.document->'items') then return '{"error":"INVALID_INPUT"}';end if;
  select * into old from public.library_responses where run_id=r.id and student_id=(p_input->>'studentId')::uuid;
  if found and old.answers=p_input->'answers' and old.status=p_input->>'status' then return pn_private.library_detail(r);end if;
  if coalesce(old.revision,0)<>(p_input->>'revision')::integer then return '{"error":"CONFLICT"}';end if;
  select count(*) into score from jsonb_array_elements(v.document->'items') with ordinality q(item,n) where item->>'key'=p_input->'answers'->>((n-1)::integer);
  insert into public.library_responses(run_id,student_id,answers,correct,status) values(r.id,(p_input->>'studentId')::uuid,p_input->'answers',score,p_input->>'status') on conflict(run_id,student_id) do update set answers=excluded.answers,correct=excluded.correct,status=excluded.status,revision=library_responses.revision+1,updated_at=now();
  return pn_private.library_detail(r);
 end if;return '{"error":"INVALID_INPUT"}';
exception when unique_violation then return '{"error":"CONFLICT"}';when invalid_text_representation or datetime_field_overflow then return '{"error":"INVALID_INPUT"}';
end $$;
revoke all on function public.library_action(jsonb,uuid) from public,anon;grant execute on function public.library_action(jsonb,uuid) to authenticated;

create function public.library_board(p_presentation uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.library_runs;d jsonb;i jsonb;safe jsonb;
begin
 if coalesce(auth.jwt()->>'is_anonymous','')<>'true' then return '{"error":"FORBIDDEN"}';end if;
 select rr.* into r from public.library_runs rr join pn_private.presentations p on p.session_id=rr.id where p.id=p_presentation and p.board_id=auth.uid() and not p.revoked and p.expires_at>now();
 if not found then return 'null'::jsonb;end if;
 select document into d from public.question_versions where set_id=r.set_id and version=r.version;i=d->'items'->r.position;
 safe=jsonb_build_object('id',i->'id','kind',i->'kind','prompt',i->'prompt');
 if i->>'kind'='card' then safe=safe||jsonb_build_object('options',i->'options');elsif i->>'kind'='interactive' then safe=safe||jsonb_build_object('tool',i->'tool');end if;
 return jsonb_build_object('id',r.id,'title',d->'title','position',r.position,'total',jsonb_array_length(d->'items'),'revision',r.revision,'status',r.status,'item',safe);
end $$;
revoke all on function public.library_board(uuid) from public,anon;grant execute on function public.library_board(uuid) to authenticated;
commit;
